#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int v[505];
    int present[505] = {0};
    int unique[505];
    int u_count = 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
        if (!present[v[i]]) {
            present[v[i]] = 1;
            unique[u_count++] = v[i];
        }
    }

    if (n <= 2) {
        printf("%d\n", n);
        return 0;
    }

    int max_len = 1;

    for (int i = 0; i < u_count; i++) {
        int a = unique[i];
        for (int j = i + 1; j < u_count; j++) {
            int b = unique[j];
            int len = 0;
            int last = 0;

            for (int k = 0; k < n; k++) {
                if (v[k] == a || v[k] == b) {
                    if (v[k] != last) {
                        len++;
                        last = v[k];
                    }
                }
            }

            if (len > max_len) {
                max_len = len;
            }
        }
    }

    printf("%d\n", max_len);

    return 0;
}
